def solve():
    for n in range(3, 10):
        for k in range(1, (n // 2) + 1):
            if n == 2 * k:
                continue
            # Number of binary strings of length n is 2^n
            # Let's check if D(S) uniquely determines S
            # D(S) = {T : d(S, T) = k}
            # S is a binary string of length n
            # We can represent strings as integers
            strings = []
            for i in range(2**n):
                strings.append(bin(i)[2:].zfill(n))

            sets = []
            for s in strings:
                d_s = []
                for t in strings:
                    dist = sum(1 for i in range(n) if s[i] != t[i])
                    if dist == k:
                        d_s.append(t)
                sets.append(tuple(sorted(d_s)))

            # Check if all sets are unique
            unique_sets = set()
            duplicate = False
            for s in sets:
                if s in unique_sets:
                    duplicate = True
                    break
                unique_sets.add(s)

            if duplicate:
                print(f"n={n}, k={k}: duplicate set found!")
            else:
                print(f"n={n}, k={k}: all sets unique")

